package com.shikshasetu.controller;
import com.shikshasetu.model.*;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/fairness") public class FairnessController{
 private final StudentRepository students;private final RiskAssessmentRepository risks;public FairnessController(StudentRepository s,RiskAssessmentRepository r){students=s;risks=r;}
 @GetMapping("/audit") public Map<String,Object> audit(){PortalPrincipal p=PortalAuthContext.require();List<Student> visible=p.isSuperAdmin()?students.findAll():students.findAllByInstitutionId(p.institutionId());Set<Long> ids=new HashSet<>();visible.forEach(s->ids.add(s.getId()));Map<Long,RiskAssessment> latest=new HashMap<>();for(RiskAssessment r:risks.findAllByOrderByAssessedAtDesc())if(ids.contains(r.getStudentId()))latest.putIfAbsent(r.getStudentId(),r);Map<String,List<RiskAssessment>> groups=new TreeMap<>();for(Student s:visible){if(s.getAuditGroup()==null||s.getAuditGroup().isBlank())continue;RiskAssessment r=latest.get(s.getId());if(r!=null)groups.computeIfAbsent(s.getAuditGroup(),k->new ArrayList<>()).add(r);}Map<String,Object> result=new TreeMap<>();groups.forEach((g,rs)->{long high=rs.stream().filter(r->"HIGH".equals(r.getRiskBand())).count();result.put(g,Map.of("assessedCount",rs.size(),"highRiskCount",high,"highRiskRate",rs.isEmpty()?0.0:(double)high/rs.size()));});return Map.of("groups",result,"notice","Descriptive parity check only. Small samples and differing needs can distort comparisons; investigate with human review. Audit groups are not used in risk scoring.");}
}
